<div class="grid grid-cols-1 gap-6 md:grid-cols-3">
    <!-- Card 1: Security -->
    <div class="lp-tilt group relative space-y-4 overflow-hidden rounded-3xl border border-gray-200 bg-white p-8 text-right shadow-sm transition-all duration-300 hover:-translate-y-1 hover:border-yellow-500/60 hover:shadow-xl hover:shadow-yellow-500/10 dark:border-gray-800 dark:bg-gray-900 dark:hover:border-yellow-500/60">
        <div class="pointer-events-none absolute -left-6 -top-6 h-24 w-24 rounded-full bg-red-500/10 blur-2xl transition-opacity duration-300 group-hover:opacity-100 opacity-0"></div>
        <div class="flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-red-50 to-red-100 text-red-600 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-3 dark:from-red-900/30 dark:to-red-900/10 dark:text-red-400">
            <svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/>
            </svg>
        </div>
        <h3 class="text-xl font-bold text-gray-900 dark:text-white">امنیت کامل</h3>
        <p class="leading-relaxed text-gray-600 dark:text-gray-400">
            حفاظت پیشرفته از سرمایه‌های شما با استفاده از استانداردهای جهانی رمزنگاری و امنیت تراکنش‌ها.
        </p>
        <div class="h-1 w-10 rounded-full bg-gradient-to-l from-red-400 to-red-600 opacity-0 transition-opacity duration-300 group-hover:opacity-100"></div>
    </div>

    <!-- Card 2: Speed -->
    <div class="lp-tilt group relative space-y-4 overflow-hidden rounded-3xl border border-gray-200 bg-white p-8 text-right shadow-sm transition-all duration-300 hover:-translate-y-1 hover:border-yellow-500/60 hover:shadow-xl hover:shadow-yellow-500/10 dark:border-gray-800 dark:bg-gray-900 dark:hover:border-yellow-500/60">
        <div class="pointer-events-none absolute -left-6 -top-6 h-24 w-24 rounded-full bg-green-500/10 blur-2xl transition-opacity duration-300 group-hover:opacity-100 opacity-0"></div>
        <div class="flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-green-50 to-green-100 text-green-600 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-3 dark:from-green-900/30 dark:to-green-900/10 dark:text-green-400">
            <svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
            </svg>
        </div>
        <h3 class="text-xl font-bold text-gray-900 dark:text-white">سرعت در اجرا</h3>
        <p class="leading-relaxed text-gray-600 dark:text-gray-400">
            تراکنش‌های شما در کسری از ثانیه پردازش شده و موجودی شما به صورت آنی به‌روزرسانی می‌شود.
        </p>
        <div class="h-1 w-10 rounded-full bg-gradient-to-l from-green-400 to-green-600 opacity-0 transition-opacity duration-300 group-hover:opacity-100"></div>
    </div>

    <!-- Card 3: Trust -->
    <div class="lp-tilt group relative space-y-4 overflow-hidden rounded-3xl border border-gray-200 bg-white p-8 text-right shadow-sm transition-all duration-300 hover:-translate-y-1 hover:border-yellow-500/60 hover:shadow-xl hover:shadow-yellow-500/10 dark:border-gray-800 dark:bg-gray-900 dark:hover:border-yellow-500/60">
        <div class="pointer-events-none absolute -left-6 -top-6 h-24 w-24 rounded-full bg-blue-500/10 blur-2xl transition-opacity duration-300 group-hover:opacity-100 opacity-0"></div>
        <div class="flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-blue-50 to-blue-100 text-blue-600 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-3 dark:from-blue-900/30 dark:to-blue-900/10 dark:text-blue-400">
            <svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
            </svg>
        </div>
        <h3 class="text-xl font-bold text-gray-900 dark:text-white">شفافیت و اعتماد</h3>
        <p class="leading-relaxed text-gray-600 dark:text-gray-400">
            با قیمت‌های لحظه‌ای و بدون کارمزدهای پنهان، هر معامله را با اطمینان کامل انجام دهید.
        </p>
        <div class="h-1 w-10 rounded-full bg-gradient-to-l from-blue-400 to-blue-600 opacity-0 transition-opacity duration-300 group-hover:opacity-100"></div>
    </div>
</div>
